<?php
require_once __DIR__ . '/../../includes/auth.php'; require_role('admin');
$userId = filter_input(INPUT_GET, 'id', FILTER_VALIDATE_INT); if (!$userId || $userId < 1) { flash_set('error', 'Invalid user ID specified.'); redirect('modules/users/index.php'); }
try { $stmt = $conn->prepare('SELECT user_id, username, email, full_name, role, is_active FROM users WHERE user_id = ? LIMIT 1'); if (!$stmt) throw new RuntimeException($conn->error); $stmt->bind_param('i', $userId); $stmt->execute(); $user = $stmt->get_result()->fetch_assoc(); $stmt->close(); if (!$user) { flash_set('error', 'User record not found.'); redirect('modules/users/index.php'); } } catch (Throwable $e) { error_log('Database exception loading user for edit: ' . $e->getMessage()); flash_set('error', 'A database error occurred while retrieving the user.'); redirect('modules/users/index.php'); }
$pageTitle = 'Edit User'; $currentNav = 'users'; $errors = $_SESSION['_form_errors'] ?? []; $old = $_SESSION['_form_old'] ?? []; unset($_SESSION['_form_errors'], $_SESSION['_form_old']); $selectedRole = $old['role'] ?? $user['role']; $selectedStatus = $old['is_active'] ?? (string)$user['is_active'];
$displayUsername = '@' . ltrim($user['username'], '@');
include __DIR__ . '/../../includes/header.php'; include __DIR__ . '/../../includes/sidebar.php';
?>
